        MethodDeclarationSyntax nonLifecycleCaller = nonLifecycle.SyntaxTrees.Single().GetRoot().DescendantNodes().OfType<MethodDeclarationSyntax>().Single(static method => method.Identifier.ValueText == "Caller");

